  Lemma heap_wbytes : forall LB cr M VM (A n a : Z) bs,
    hi_heap HI LB cr M VM -> In (A, n) LB -> A <= a -> a + Z.of_nat (length bs) <= A + n -> A + n <= 2 ^ 64 ->
